script:
$env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
"=== testing Hermes with Space Bunny ==="
$job = Start-Job -ScriptBlock {
  $env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
  hermes -p "Reply with exactly: HERMES_OK" 2>&1 | Select-Object -First 10
}
if (Wait-Job $job -Timeout 60) {
  Receive-Job $job
} else {
  "TIMED OUT after 60s"
  Stop-Job $job
}
Remove-Job $job -Force
